case = int(input())
for _ in range(case):
	(n, k) = map(int, input().split(' '))
	s = input()
	arr = []
	if n & 1 == 1:
		value = n // 2
		for i in range(value):
			arr.append(i + 1)
		for i in range(value, n):
			arr.append(value)
			value -= 1
	else:
		value = n // 2
		for i in range(value):
			arr.append(i + 1)
		for i in range(value, n):
			value -= 1
			arr.append(value)
	ans = 0
	if k <= n // 2:
		ans = k
	else:
		ans = n - k
	res = 0
	for i in range(n - 1):
		if s[i] != s[i + 1]:
			if arr[i] <= ans:
				res += arr[i]
			else:
				res += ans
	print(res)
